export type SlotBinding =
  | { readonly from: "input"; readonly input_name: string; readonly path?: string | null }
  | { readonly from: "context"; readonly path: string }
  | { readonly from: "literal"; readonly value: string }
  | { readonly from: "item"; readonly path: string }
  | { readonly from: "context_lookup"; readonly collection_path: string; readonly collection_key_path: string; readonly item_key_path: string; readonly value_path: string }
  /**
   * `context_lookup`'s sibling, keyed off a named input instead of the run
   * context. A fan-out unit needs values chosen by something it carries — a
   * cohort looking up the repository it builds in — and `input` alone cannot
   * key off the item. The difference from `context_lookup` is only where the
   * collection comes from: an upstream stage's typed output rather than a
   * pointer into an untyped bag.
   */
  | { readonly from: "input_lookup"; readonly input_name: string; readonly collection_key_path: string; readonly item_key_path: string; readonly value_path: string };

export type Bindable = string | SlotBinding;
export interface WorktreeIdentity { readonly branchName: string; readonly worktreeSubdir: string; readonly baseRef?: string }
export interface WorktreeTemplate { readonly branch_name: Bindable; readonly worktree_subdir: Bindable; readonly base_ref?: Bindable }

export interface FanOutDefinition {
  readonly over: SlotBinding;
  readonly unit_id_path: string;
  readonly session_mode?: "per_unit" | "shared";
  readonly depends_on_path?: string | null;
  readonly max_parallel?: number;
import type { MaterializedExecutionUnit } from "../domain/compiled-workflow";
import { isDelegatedRuntimeId, type Bindable, type DelegatedSessionDefinitionConfig, type ResolvedExecutorConfig, type SessionIdentity, type SessionLaunchReason, type SlotBinding } from "../domain/delegated-session";
import type { ArtifactEnvelope } from "../domain/execution";
import { err, ok, type JsonValue, type Result, type StageInstanceId, type WorkflowRunId } from "../domain/primitives";
import { readJsonPointer } from "../domain/json-pointer";
import type { StageOperatorRole } from "../domain/workflow";

export interface ResolveExecutionError {
  readonly operation: "resolve_execution";
  readonly detail: string;
  /** A diagnostic rendering that is never dispatchable, but always shows the generated contract for a selected role. */
  readonly rendered_prompt?: string;
}
export interface BindingEnvironment {
  readonly inputs: Readonly<Record<string, ArtifactEnvelope | readonly ArtifactEnvelope[]>>;
  readonly context: JsonValue;
  readonly item: JsonValue | null;
}
export interface ResolveDelegatedExecutionInput {
  readonly definition: DelegatedSessionDefinitionConfig;
  readonly environment: BindingEnvironment;
  readonly unit: MaterializedExecutionUnit;
  readonly stage_instance_id: StageInstanceId;
  readonly prompt_template: string;
  readonly run_id: WorkflowRunId;
  readonly operator_role: StageOperatorRole | null;
  readonly launch_reason?: SessionLaunchReason;
}


const stringify = (value: JsonValue): string => typeof value === "string" ? value : value === null ? "null" : typeof value === "object" ? JSON.stringify(value) : String(value);
const inputBindingValue = (input: ArtifactEnvelope | readonly ArtifactEnvelope[]): JsonValue => Array.isArray(input)
  ? input.map((artifact) => ({ unit_id: artifact.unit_id, artifact: artifact.body }))
  : (input as ArtifactEnvelope).body;

export const resolveBindingValue = (binding: SlotBinding, environment: BindingEnvironment): Result<JsonValue, ResolveExecutionError> => {
  if (binding.from === "literal") return ok(binding.value);
  if (binding.from === "input") {
    const input = environment.inputs[binding.input_name];
    if (!input) return err({ operation: "resolve_execution", detail: `input '${binding.input_name}' not found` });
    const source = inputBindingValue(input);
    const value = binding.path == null ? source : readJsonPointer(source, binding.path);
    return value === undefined ? err({ operation: "resolve_execution", detail: `input pointer '${binding.path}' not found` }) : ok(value);
  }
  if (binding.from === "context") {
    const value = readJsonPointer(environment.context, binding.path);
    return value === undefined ? err({ operation: "resolve_execution", detail: `context pointer '${binding.path}' not found` }) : ok(value);
  }
  if (binding.from === "item") {
    if (environment.item === null) return err({ operation: "resolve_execution", detail: "item binding used outside fan-out" });
    const value = readJsonPointer(environment.item, binding.path);
    return value === undefined ? err({ operation: "resolve_execution", detail: `item pointer '${binding.path}' not found` }) : ok(value);
  }
  // Both lookups pick one entry out of a collection using a key the fan-out item
  // carries. They differ only in where the collection comes from — the run
  // context, or a named input holding an upstream stage's typed output.
  const lookup = binding.from === "context_lookup" ? "context lookup" : "input lookup";
  if (environment.item === null) return err({ operation: "resolve_execution", detail: `${lookup} used outside fan-out` });
  const itemKey = readJsonPointer(environment.item, binding.item_key_path);
  if (typeof itemKey !== "string" || itemKey.length === 0) return err({ operation: "resolve_execution", detail: `${lookup} item key '${binding.item_key_path}' must be a non-empty string` });
  let collection: JsonValue | undefined;
  let source: string;
  if (binding.from === "context_lookup") {
    collection = readJsonPointer(environment.context, binding.collection_path);
    source = binding.collection_path;
  } else {
    const input = environment.inputs[binding.input_name];
    if (!input) return err({ operation: "resolve_execution", detail: `input '${binding.input_name}' not found` });
    collection = inputBindingValue(input);
    source = binding.input_name;
  }
  if (!Array.isArray(collection)) return err({ operation: "resolve_execution", detail: `${lookup} collection '${source}' must be an array` });
  const matches = collection.filter((entry) => readJsonPointer(entry, binding.collection_key_path) === itemKey);
  if (matches.length !== 1) return err({ operation: "resolve_execution", detail: `${lookup} key '${itemKey}' matched ${matches.length} entries in '${source}'` });
  const value = readJsonPointer(matches[0] as JsonValue, binding.value_path);
  return value === undefined ? err({ operation: "resolve_execution", detail: `${lookup} value '${binding.value_path}' not found` }) : ok(value);
};

export const resolveBinding = (binding: SlotBinding, environment: BindingEnvironment): Result<string, ResolveExecutionError> => {
  const value = resolveBindingValue(binding, environment);
  return value.ok ? ok(stringify(value.value)) : value;
};

const resolveBindable = (value: Bindable | undefined, environment: BindingEnvironment): Result<string | null, ResolveExecutionError> => {
  if (value === undefined) return ok(null);
  if (typeof value === "string") return ok(value);
  const resolved = resolveBindingValue(value, environment);
  return resolved.ok ? ok(resolved.value === null ? null : stringify(resolved.value)) : resolved;
};

/**
 * A small builder so each `derive` test case reads as facts, not fixtures.
 * Every id is derived deterministically from `RUN_ID` via `src/decision/ids`,
 * exactly as production would compute it.
 */
import { createHash } from "node:crypto";

import type { CompiledStageContract, CompiledWorkflowDefinition } from "../../src/domain/compiled-workflow";
import { fingerprintOf, runUnitIdFor, stageInstanceIdFor } from "../../src/decision/ids";
import type { AvailableArtifact, RunSnapshot, StagePolicy, StageSnapshot, UnitSnapshot } from "../../src/decision/snapshot";
import type { ArtifactId, InputFingerprint, JsonValue, OutputSlotVersion, RunRecordVersion, RunUnitId, StageInstanceId, UnitId, WaitId, WorkflowDefinitionId, WorkflowRunId, WorkOrderId } from "../../src/domain/primitives";
import type { RunOutputSlot, RunStage, UnitState, WorkflowRun, WorkOrder } from "../../src/domain/run-record";
import type { Wait } from "../../src/domain/wait";
import type { StageKey, StageOutcome } from "../../src/domain/workflow";

/** Deterministic fixture-id generator, local to this builder — same shape as (but independent of) `src/decision/ids.ts`'s internal `stableUuid`; determinism matters for case 12 (derive is stable across repeated calls). */
const localStableUuid = (identity: string): string => {
  const hex = createHash("sha256").update(identity).digest("hex").slice(0, 32);
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-4${hex.slice(13, 16)}-8${hex.slice(17, 20)}-${hex.slice(20)}`;
};

export const RUN_ID = "11111111-1111-4111-8111-111111111111" as WorkflowRunId;
export const NOW = "2026-08-29T12:00:00.000Z";
export const PRODUCER_STAGE_KEY = "brief_writer" as StageKey;
export const PRODUCER_OUTPUT_NAME = "brief";

const definitionId = "66666666-6666-4666-8666-666666666666" as WorkflowDefinitionId;

export const run = (options?: { readonly context?: JsonValue; readonly state?: WorkflowRun["state"]; readonly outcome?: StageOutcome | null; readonly record_version?: number }): WorkflowRun => ({
  id: RUN_ID, workflow_definition_id: definitionId, workflow_definition_version: 1,
  bundle_pin: { definition_version: 1, prompt_bundle_hash: "test-bundle", adapter_version: "test-adapter", artifact_schema_version: "test-artifacts" },
  context: options?.context ?? {}, state: options?.state ?? "active", outcome: options?.outcome ?? null,
  record_version: (options?.record_version ?? 1) as RunRecordVersion, created_at: NOW, ended_at: null,
});

export const emptyDefinition = (): CompiledWorkflowDefinition => ({ manifest_version: 1, stages: {}, edges: [], transitions: [], source_stages: [] });

/** One stage per key, `scalar` materialization — enough for run-completion (§D) tests that only care about stage membership. */
export const scalarStageDefinition = (stage_keys: readonly string[]): CompiledWorkflowDefinition => ({
  manifest_version: 1,
  stages: Object.fromEntries(stage_keys.map((key): [string, CompiledStageContract] => [key, {
    stage_key: key as StageKey, stage_type: "delegated_session", operator_role: null, inputs: [], outputs: [],
    materialization: { kind: "scalar" }, executor: { executor_type: "delegated_session", definition_config: {} },
  }])),
  edges: [], transitions: [], source_stages: stage_keys as StageKey[],
});

/**
 * A fan-out consumer at `stage_key`, driven over a `unit_complete` edge from a
 * `brief_writer` producer — the dev-flow `build` shape spec §4 describes. The
 * driver item shape is `{ unit_id: artifact.unit_id, artifact: artifact.body }`
 * (`resolveBindingValue`'s `inputBindingValue`), so `unit_id_path` is `/unit_id`
 * and `depends_on_path` is `/artifact/depends_on`.
 *
 * `brief_writer` is deliberately NOT a key of `definition.stages`: `derive`'s
 * materialization loop (§B) only visits definition stages, and every
 * producer-side fact it needs — readiness, closure — comes from
 * `available_artifacts` and an optional `StageSnapshot` row, both independent
 * of the definition. A test that wants `brief_writer` "finished" stores that
 * row directly (`stage({ stage_key: PRODUCER_STAGE_KEY, materialization_closed: true, units: [...] })`);
 * one that wants the collection "open" simply never stores it.
 */

